import http.client,json,socket,urllib.parse,sys
u=urllib.parse.urlparse(sys.argv[1]);out={"resolved":sorted(set(x[4][0] for x in socket.getaddrinfo(u.hostname,u.port,type=socket.SOCK_STREAM))),"requests":[]}
for path in ["/v1/models","/api/ps"]:
 try:
  h=http.client.HTTPConnection(u.hostname,u.port,timeout=5);h.request("GET",path);res=h.getresponse();raw=res.read((1<<20)+1);h.close();assert len(raw)<=1<<20;d=json.loads(raw);row={"path":path,"status":res.status}
  if path=="/v1/models":row["models"]=[x["id"]for x in d.get("data",[])]
  else:row["loadedModels"]=[{"name":x.get("name"),"size":x.get("size"),"sizeVram":x.get("size_vram"),"contextLength":x.get("context_length"),"expiresAt":x.get("expires_at")}for x in d.get("models",[])]
  out["requests"].append(row)
 except Exception as exc:out["requests"].append({"path":path,"errorClass":type(exc).__name__})
print(json.dumps(out))
